'use strict';
const $=id=>document.getElementById(id);
const labels={confirmed:'漏洩を確認',possible:'漏洩の可能性',mixed:'確認済み・可能性あり',access:'権限外の閲覧を確認',denied:'続報で漏洩を否定',catalogue:'HIBP検証済み',announcement:'公式発表あり・内容は要確認',needsReview:'出典更新あり・再確認待ち'};
const state={records:[],tab:'all',page:1,pageSize:10,saved:new Set(),storage:true};
async function loadUpdateStatus(){const target=$('updateStatus');if(!target)return;try{const response=await fetch('update-status.json',{cache:'no-cache'});if(!response.ok)throw new Error('Status unavailable');const x=await response.json();const date=x.lastAttemptAt?new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tokyo'}).format(new Date(x.lastAttemptAt)):'未実行';const stale=x.lastAttemptAt&&(Date.now()-Date.parse(x.lastAttemptAt)>3*60*60*1000);const result=x.status==='complete'?'情報源を確認しました':x.status==='partial'?'一部の情報源を確認できませんでした（'+x.failedFetches+'件）':'情報源を確認できませんでした';target.textContent='自動確認の設定：毎時17分（日本時間。実行開始が遅れる場合があります） ／ 前回の確認：'+date+' ／ '+result+(stale?'。確認日時が古くなっています。':'。')+'最新の対象範囲は各社の公式案内をご確認ください。';}catch{target.textContent='情報の更新状況を取得できませんでした。最新の内容は各社の公式案内をご確認ください。';}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKC').toLocaleLowerCase('ja').trim();
const safeUrl=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:'#'}catch{return '#'}};
const sourceNames={'innovatopia.jp':'innovaTopia','security-next.com':'Security NEXT','scan.netsecurity.ne.jp':'ScanNetSecurity','internet.watch.impress.co.jp':'INTERNET Watch','itmedia.co.jp':'ITmedia NEWS','news.yahoo.co.jp':'Yahoo!ニュース','yahoo.co.jp':'Yahoo!ニュース','nikkei.co.jp':'日本経済新聞','nikkei.com':'日本経済新聞','asahi.com':'朝日新聞デジタル','mainichi.jp':'毎日新聞','yomiuri.co.jp':'読売新聞オンライン','sankei.com':'産経ニュース','oricon.co.jp':'ORICON NEWS'};
function sourceSiteName(url){try{const host=new URL(url).hostname.toLowerCase().replace(/^www\\./,'');const key=Object.keys(sourceNames).sort((a,b)=>b.length-a.length).find(x=>host===x||host.endsWith('.'+x));return key?sourceNames[key]:host}catch{return '出典サイト'}}
function sourceAttribution(r,detail=false){
 const entries=[];const seen=new Set();
 const add=(url,label,primary=false)=>{const href=safeUrl(url);if(href==='#'||seen.has(href))return;seen.add(href);entries.push({href,label:label+'（'+sourceSiteName(href)+'）',primary})};
 if(r.sourceType==='hibp')add(r.source,'事例情報');else add(r.source,'公式発表・確認資料',true);
 if(r.automaticSummary?.evidenceSource&&r.automaticSummary.evidenceSource!==r.source)add(r.automaticSummary.evidenceSource,'自動要約の根拠資料');
 for(const url of r.additionalSources||[])add(url,'関連する公式発表');
 for(const url of r.newsSources||[])add(url,'発見の手がかり');
 if(!entries.length)return '';
 const cls=detail?'detail-source-attribution':'source-attribution';
 return '<div class="'+cls+'"><span class="field-label">この事案の情報源</span><div class="source-attribution-links">'+entries.map(x=>'<a class="'+(x.primary&&!detail&&needsOfficialReview(r)?'official-source-cta':'source-link')+'" href="'+esc(x.href)+'" target="_blank" rel="noopener noreferrer">'+esc(x.label)+' ↗</a>').join('')+'</div></div>'
}
const displayDate=s=>s?s.replaceAll('-','.'):'未公表';
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
function getSaved(){try{const ids=JSON.parse(localStorage.getItem('mofu-leakcheck-saved')||'[]');if(Array.isArray(ids))state.saved=new Set(ids.filter(id=>typeof id==='string'&&state.records.some(r=>r.id===id)))}catch{state.storage=false}}
function save(id){if(!state.records.some(r=>r.id===id))return;if(state.saved.has(id)){state.saved.delete(id);toast('「あとで確認」から外しました')}else{state.saved.add(id);toast(state.storage?'「あとで確認」に保存しました':'この画面の「あとで確認」に追加しました')}try{localStorage.setItem('mofu-leakcheck-saved',JSON.stringify([...state.saved]))}catch{state.storage=false;toast('保存機能が制限されています。この画面を開いている間だけ保持します。')}render();const target=[...document.querySelectorAll('[data-save]')].find(x=>x.dataset.save===id);if(target)target.focus({preventScroll:true})}
function badge(r){return `<span class="badge ${esc(r.status)}">${esc(labels[r.status]||'出典を確認')}</span>`}
function showNewMark(r){if(r.automaticallyCollected===true)return true;const latest=state.records.filter(x=>x.sourceType==='official'&&x.updated).reduce((m,x)=>x.updated>m?x.updated:m,'');return r.sourceType==='official'&&Boolean(latest)&&r.updated===latest}
function card(r){const saved=state.saved.has(r.id);return `<article class="incident" aria-labelledby="title-${esc(r.id)}"><div class="incident-top"><div><div class="company-line"><h3 id="title-${esc(r.id)}">${esc(r.company)}</h3><span class="category-tag">${esc(r.category)}</span></div><p class="service-title">${esc(r.service)}</p></div><button class="bookmark ${saved?'saved':''}" data-save="${esc(r.id)}" aria-pressed="${saved}" aria-label="${esc(r.service)}を${saved?'あとで確認から外す':'あとで確認に保存'}"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 2h10v16l-5-3-5 3Z"/></svg></button></div><div class="incident-sub">${badge(r)}${showNewMark(r)?'<span class="new-mark" aria-label="新着">NEW</span>':''}<span class="source-date">${r.sourceType==='hibp'?`事例発生日 ${esc(displayDate(r.eventDate))} ・ 海外サービス`:`公表 ${esc(displayDate(r.published))}${r.updated!==r.published?` ・ 資料更新 ${esc(displayDate(r.updated))}`:''}`}</span></div><div class="public-scale"><span class="field-label">公表されている件数・範囲</span><p>${esc(r.scale||"件数は未確認です。公式発表をご確認ください。")}</p></div><div class="impact-grid"><div class="audience"><span class="field-label">${r.status==='denied'?'続報の結論':'対象となる登録・利用（公表範囲）'}</span><p>${esc(r.audience)}</p></div><div class="data-block"><span class="field-label">${r.status==='denied'?'現在の公表状況':'公表資料に記載された情報項目'}</span><div class="tags">${r.items.length?r.items.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):`<span class="tag">${r.status==='denied'?'漏洩はなかったと判断した旨を公表':'情報項目は未確認。出典本文をご確認ください。'}</span>`}</div></div></div>${r.excluded&&r.excluded.trim()!=='対象外の情報は推測していません。'?`<p class="exclude"><b>${r.status==='denied'?'訂正内容：':'対象外・補足：'}</b>${esc(r.excluded)}</p>`:''}<div class="incident-foot"><span>${r.automaticallyCollected?'公式ページを自動取得':r.sourceChanged?'出典の再確認が必要':'資料確認 '+esc(displayDate(r.verifiedAt))}</span><div class="actions"><button class="textbtn" data-detail="${esc(r.id)}">対象条件・詳細</button><a class="source-link" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">${r.sourceType==='hibp'?'出典：HIBP':'公式発表を読む'} ↗</a></div></div></article>`}
function filtered(){const words=norm($('query').value).split(/[\s、,]+/).filter(Boolean);return state.records.filter(r=>{if(state.tab==='saved'&&!state.saved.has(r.id))return false;if(['official','hibp'].includes(state.tab)&&r.sourceType!==state.tab)return false;if($('category').value!=='all'&&r.category!==$('category').value)return false;if($('status').value!=='all'&&r.status!==$('status').value)return false;if($('dataType').value!=='all'&&!r.items.join(' ').includes($('dataType').value))return false;const text=norm([r.company,r.service,r.aliases,serviceSearchText(r),r.audience,...r.items].join(' '));return words.every(w=>text.includes(w))}).sort((a,b)=>$('sort').value==='name'?a.company.localeCompare(b.company,'ja'):b.updated.localeCompare(a.updated)||a.company.localeCompare(b.company,'ja'))}
function companyGroups(rs){const groups=new Map();for(const r of rs){const key=norm(r.company).replace(/株式会社|有限会社|[\s・（）()]/g,'');if(!groups.has(key))groups.set(key,{company:r.company,records:[]});groups.get(key).records.push(r)}return [...groups.values()]}

function automaticField(r,kind){return (r.automaticSummary?.passages||[]).find(x=>x.kind===kind)?.quote||''}
function automaticPending(r){const reason=r.automaticSummary?.reason;return reason==='source_fetch_failed'?'公式発表を取得できなかったため、自動要約を表示していません。次回の更新で再取得します。':reason==='document_text_unreadable'?'資料の本文を読み取れず、自動要約を作成できませんでした。公式発表をご確認ください。':'公式本文からこの項目の記載を特定できませんでした。次回の更新でも再処理します。公式発表をご確認ください。'}
function automaticOverview(r){const fields=[['audience','対象の登録・利用'],['items','情報項目']];const seen=new Set();const parts=[];for(const [key,label] of fields){const quote=automaticField(r,key);if(quote&&quote!==automaticField(r,'scale')&&!seen.has(quote)){seen.add(quote);parts.push(label+'：'+quote)}}return parts.length?'公式本文からの自動要約（原文抜粋） '+parts.join(' ／ '):automaticField(r,'scale')?'対象条件・情報項目についても、公表件数・範囲欄の公式本文抜粋をご確認ください。':automaticPending(r)}
function automaticDetail(r,kind){const quote=automaticField(r,kind);return quote?'公式本文の記載（自動抽出）：'+quote:automaticPending(r)}

function needsOfficialReview(r){return r.automaticallyCollected===true||r.sourceChanged===true||r.status==='announcement'||r.status==='needsReview'}
let serviceNameIndex={byId:{},bySource:{}};
function serviceInfo(r){const entry=(serviceNameIndex.byId||{})[r.id]||(serviceNameIndex.bySource||{})[r.source]||{};const names=Array.isArray(entry.names)?entry.names.filter(x=>typeof x==='string'&&x.trim()):Array.isArray(r.serviceNames)?r.serviceNames.filter(x=>typeof x==='string'&&x.trim()):[];const scope=typeof entry.scope==='string'?entry.scope:!r.automaticallyCollected?r.service:'';return {names,scope,evidence:Array.isArray(entry.evidence)?entry.evidence:[]}}
function serviceSearchText(r){const info=serviceInfo(r);return [...info.names,info.scope].join(' ')}
function companyServices(g){const infos=g.records.map(serviceInfo);const names=[...new Set(infos.flatMap(x=>x.names))];const scopes=[...new Set(infos.map(x=>x.scope).filter(Boolean))];const text=names.length?names.join(' ／ '):scopes.length?scopes.join(' ／ '):'サービス名・対象区分は確認中';return `<p class="company-services"><span class="company-services-label">関連サービス・登録区分</span><strong>${esc(text)}</strong></p>`}
function companyCard(g){
 const rs=[...g.records].sort((a,b)=>b.updated.localeCompare(a.updated));
 const latest=rs[0];
 const reviewed=rs.filter(r=>!r.automaticallyCollected);
 const primary=reviewed.length?reviewed:rs.slice(0,1);
 const items=[...new Set(primary.flatMap(r=>r.items))];
 const archive=rs.filter(r=>!primary.includes(r));
 const showItems=items.length>0||!primary.some(needsOfficialReview);
 return `<article class="company-group"><header class="company-group-head"><div class="company-identity"><h2>${esc(g.company)}</h2>${companyServices(g)}</div><span>\u8cc7\u6599\u66f4\u65b0 ${esc(displayDate(latest.updated))}</span></header><div class="company-summary"><div class="incident-sub">${[...new Set(primary.map(r=>r.status))].map(status=>badge({status})).join('')}${rs.some(showNewMark)?'<span class="new-mark">\u65b0\u7740</span>':''}</div>${showItems?`<span class="field-label">\u516c\u8868\u8cc7\u6599\u306b\u8a18\u8f09\u3055\u308c\u305f\u60c5\u5831\u9805\u76ee</span><div class="tags">${items.length?items.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):'\u60c5\u5831\u9805\u76ee\u306f\u672a\u78ba\u8a8d'}</div>`:''}<div class="scope-list">${primary.map(r=>{
  const pending=needsOfficialReview(r);
  const summary=(r.automaticallyCollected||r.sourceChanged)&&r.automaticSummary?automaticOverview(r):r.automaticallyCollected?'\u516c\u5f0f\u767a\u8868\u3078\u306e\u30ea\u30f3\u30af\u3092\u63b2\u8f09\u3057\u3066\u3044\u307e\u3059\u3002\u5bfe\u8c61\u6761\u4ef6\u30fb\u60c5\u5831\u9805\u76ee\u306e\u8981\u7d04\u306f\u672a\u4f5c\u6210\u3067\u3059\u3002自動要約の結果を取得できていません。公式発表をご確認ください。':r.sourceChanged?'\u51fa\u5178\u306b\u66f4\u65b0\u304c\u3042\u308a\u3001\u63b2\u8f09\u5185\u5bb9\u3092\u518d\u78ba\u8a8d\u4e2d\u3067\u3059\u3002\u6700\u65b0\u306e\u5bfe\u8c61\u7bc4\u56f2\u306f\u516c\u5f0f\u767a\u8868\u3092\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002':pending?'\u516c\u5f0f\u767a\u8868\u3092\u78ba\u8a8d\u3057\u307e\u3057\u305f\u304c\u3001\u63b2\u8f09\u5185\u5bb9\u306f\u78ba\u8a8d\u4e2d\u3067\u3059\u3002\u5bfe\u8c61\u6761\u4ef6\u3084\u60c5\u5831\u9805\u76ee\u306f\u516c\u5f0f\u767a\u8868\u3067\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002':r.audience;
  const count=(r.automaticallyCollected||r.sourceChanged)&&r.automaticSummary?automaticDetail(r,'scale'):r.automaticallyCollected?'\u4ef6\u6570\u30fb\u5bfe\u8c61\u7bc4\u56f2\u306f\u516c\u5f0f\u767a\u8868\u3067\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044':r.sourceChanged?'\u516c\u8868\u4ef6\u6570\u30fb\u5bfe\u8c61\u7bc4\u56f2\u3092\u518d\u78ba\u8a8d\u4e2d':(r.scale||'\u516c\u8868\u4ef6\u6570\u306f\u78ba\u8a8d\u3067\u304d\u3066\u3044\u307e\u305b\u3093\u3002\u516c\u5f0f\u767a\u8868\u3092\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002');
  const note=r.sourceChanged?'<p class="unconfirmed-note">更新後の内容と最新の対象範囲は、公式発表でご確認ください。</p>':'';
  return `<section class="scope-row"><div class="scope-main"><h3>${esc(r.service)}</h3>${summary.startsWith("公式本文からの自動要約（原文抜粋） ")?`<span class="field-label automatic-summary-label">公式本文からの自動要約（原文抜粋）</span><p>${esc(summary.slice("公式本文からの自動要約（原文抜粋） ".length))}</p>`:`<p>${esc(summary)}</p>`}${note}${r.excluded&&r.excluded.trim()!=='対象外の情報は推測していません。'?`<p class="scope-note">\u5bfe\u8c61\u5916\u30fb\u88dc\u8db3\uff1a${esc(r.excluded)}</p>`:''}</div><div class="scope-count"><span class="field-label">\u516c\u8868\u4ef6\u6570\u30fb\u7bc4\u56f2</span><p>${esc(count)}</p>${sourceAttribution(r)}<div class="scope-actions"><div class="scope-actions-secondary"><button class="textbtn" data-detail="${esc(r.id)}">\u5bfe\u8c61\u6761\u4ef6\u30fb\u51fa\u5178\u3092\u78ba\u8a8d</button><button class="textbtn" data-save="${esc(r.id)}">${state.saved.has(r.id)?'\u4fdd\u5b58\u6e08\u307f':'\u3042\u3068\u3067\u78ba\u8a8d'}</button></div></div></div></section>`
 }).join('')}</div>${primary.length>1||archive.length?`<p class="fine">複数の事案・サービスを掲載しています。件数の単位が異なるため合算していません。</p>`:''}${archive.length?`<details class="company-archive"><summary>\u95a2\u9023\u3059\u308b\u767a\u8868\u30fb\u7d9a\u5831\uff08${archive.length}\u4ef6\uff09</summary>${archive.map(r=>`<div class="archive-row"><span>${esc(displayDate(r.updated))}</span><button class="textbtn" data-detail="${esc(r.id)}">${esc(r.service)}</button></div>`).join('')}</details>`:''}</div></article>`
}
function render(){const rs=filtered();const groups=companyGroups(rs);const totalPages=Math.max(1,Math.ceil(groups.length/state.pageSize));state.page=Math.min(state.page,totalPages);const start=(state.page-1)*state.pageSize;const visible=groups.slice(start,start+state.pageSize);$('allCount').textContent=state.records.length;$('globalCount').textContent=state.records.filter(r=>r.sourceType==='hibp').length;document.querySelector('[data-tab="hibp"]').hidden=state.records.every(r=>r.sourceType!=='hibp');$('savedCount').textContent=state.saved.size;$('resultCount').textContent=`${groups.length}社・${rs.length}件の掲載情報${groups.length?' ・ '+Math.min(start+1,groups.length)+'〜'+Math.min(start+state.pageSize,groups.length)+'社を表示中':''}`;$('list').innerHTML=visible.map(companyCard).join('');$('empty').hidden=rs.length>0;$('page-status').textContent=groups.length?`${start+1}〜${Math.min(start+state.pageSize,groups.length)}社 ／ 全${groups.length}社`:'該当する企業はありません';$('page-current').textContent=`${state.page} / ${totalPages}`;$('prev').disabled=state.page<=1;$('next').disabled=state.page>=totalPages;$('page-status-bottom').textContent=$('page-status').textContent;$('page-current-bottom').textContent=$('page-current').textContent;$('prev-bottom').disabled=$('prev').disabled;$('next-bottom').disabled=$('next').disabled;$('coverage').textContent=state.tab==='hibp'?'日本でも利用される海外サービスの直近3年の事例です。出典：Have I Been Pwned（CC BY 4.0）。日本の利用者の対象人数は確認できていません。':state.tab==='saved'?'保存されるのは事例のIDだけです。個人情報の漏洩判定をした結果ではありません。':'対象期間：直近3年。国内企業の公式発表・続報を中心に掲載。';document.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===state.tab;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))})}
function reset(){state.tab='all';state.page=1;['query'].forEach(id=>$(id).value='');['category','status','dataType'].forEach(id=>$(id).value='all');render()}
function detail(id,updateHash=true){const r=state.records.find(x=>x.id===id);if(!r)return;$('detailContent').innerHTML=`${badge(r)}<h2>${esc(r.company)}</h2><p>${esc(r.service)}</p><p class="detail-dates">${r.sourceType==='hibp'?`HIBPの事例発生日：${esc(displayDate(r.eventDate))} ／ HIBP収録日：${esc(displayDate(r.published))}`:`初回公表日：${esc(displayDate(r.published))} ／ 参照資料更新日：${esc(displayDate(r.updated))}`}<br>${r.automaticallyCollected?'公式本文の記載を毎回読み取り、自動要約を更新します。対象者の個別判定や、漏洩の確認・否定を自動で判定するものではありません。':r.sourceChanged?'旧要約の確認日：'+esc(displayDate(r.verifiedAt))+'（出典更新のため再確認待ち）':'資料確認日：'+esc(displayDate(r.verifiedAt))}</p><h3>どんな登録・利用が対象？</h3><p class="detail-scope">${esc((r.automaticallyCollected||r.sourceChanged)&&r.automaticSummary?automaticDetail(r,'audience'):r.audience)}</p><h3>公表資料に記載された情報項目</h3><p>${((r.automaticallyCollected||r.sourceChanged)&&r.automaticSummary?esc(automaticDetail(r,'items')):r.items.map(esc).join('、'))||(r.status==='denied'?'続報で漏洩はなかったと判断したとの報告を受けたと公表しています。':r.automaticallyCollected?'情報項目の整理は未完了です。公式発表の本文をご確認ください。':'この項目は確認していません。出典の本文をご確認ください。')}</p><h3>公表されている件数・範囲</h3><p>${esc((r.automaticallyCollected||r.sourceChanged)&&r.automaticSummary?automaticDetail(r,'scale'):(r.scale||'公表件数は確認できていません。公式発表をご確認ください。'))}</p><p class="fine">件数・人数・アカウント数は出典の単位を保っています。項目や区分の件数を合算した被害人数には置き換えていません。</p>${r.automaticSummary?`<p class="fine">自動要約の取得確認：${esc(new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tokyo'}).format(new Date(r.automaticSummary.checkedAt)))} ／ 本文の表記を正規化した原文抜粋です。内容全体と最新の案内は公式発表をご確認ください。</p>`:''}<h3>確認されていること・留意する点</h3><p>${esc(r.automaticallyCollected?'公式本文の該当箇所を抜粋して自動要約しています。抜粋のない項目は推測して補っていません。未公表かどうかの判定や、漏洩の有無・対象者の個別判定はしません。':r.note)}</p>${r.excluded&&r.excluded.trim()!=='対象外の情報は推測していません。'?`<h3>対象外・補足</h3><p>${esc(r.excluded)}</p>`:''}<p class="facts">この事例の公表条件と、ご自身の登録・利用履歴を照らし合わせてください。個人の情報が実際に漏洩したかは、このサイトでは判定できません。</p>${sourceAttribution(r,true)}${r.originalDescription?`<h3>出典の原文（英語）</h3><p class="original" lang="en">${esc(r.originalDescription)}</p><p class="fine">Data from <a href="https://haveibeenpwned.com/" target="_blank" rel="noopener noreferrer">Have I Been Pwned</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. 日本語の対象条件・情報項目はこのデータに基づく要約です。</p>`:''}`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;if(updateHash)history.replaceState(null,'','#'+encodeURIComponent(id))}
async function load(){try{$('loadError').hidden=true;const response=await fetch('incidents.json',{cache:'no-cache'});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!Array.isArray(data.incidents))throw new Error('Invalid catalogue');state.records=data.incidents;try{const serviceResponse=await fetch('service-names.json?v=1.3.15',{cache:'no-cache'});if(!serviceResponse.ok)throw new Error('Service names unavailable');serviceNameIndex=await serviceResponse.json()}catch{serviceNameIndex={byId:{},bySource:{}}}const opts=[...new Set(state.records.map(x=>x.category))].sort((a,b)=>a.localeCompare(b,'ja'));$('category').innerHTML='<option value="all">すべてのジャンル</option>'+opts.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');getSaved();render();await loadUpdateStatus();if(location.hash){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{}if(id)detail(id,false)}}catch(err){$('list').innerHTML='';$('resultCount').textContent='一覧を表示できませんでした';$('loadError').hidden=false;['prev','next','prev-bottom','next-bottom'].forEach(id=>$(id).disabled=true);console.error('Catalogue could not be loaded',err)}}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();state.page=1;render();$('results').scrollIntoView({behavior:'smooth'})});$('query').addEventListener('input',()=>{state.page=1;render()});document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{reset();$('query').value=b.dataset.query;render();$('results').scrollIntoView({behavior:'smooth'})}));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;state.page=1;render()}));['category','status','dataType','sort'].forEach(id=>$(id).addEventListener('change',()=>{state.page=1;render()}));$('reset').addEventListener('click',reset);$('emptyReset').addEventListener('click',reset);$('page-size').addEventListener('change',e=>{state.pageSize=Math.min(50,Math.max(10,Number(e.target.value)||10));state.page=1;render()});['prev','prev-bottom'].forEach(id=>$(id).addEventListener('click',()=>{if(state.page>1){state.page--;render();$('results').scrollIntoView({behavior:'smooth'})}}));['next','next-bottom'].forEach(id=>$(id).addEventListener('click',()=>{state.page++;render();$('results').scrollIntoView({behavior:'smooth'})}));$('retry').addEventListener('click',load);$('list').addEventListener('click',e=>{const b=e.target.closest('[data-detail],[data-save]');if(!b)return;if(b.dataset.detail)detail(b.dataset.detail);else if(b.dataset.save)save(b.dataset.save)});$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('close',()=>history.replaceState(null,'',location.pathname+location.search));$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const rect=$('detail').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('detail').close()}});window.addEventListener('hashchange',()=>{if(location.hash){try{detail(decodeURIComponent(location.hash.slice(1)),false)}catch{}}else if($('detail').open)$('detail').close()});load();



